package ru.neverland.archaeology;
import java.util.*;
import static ru.neverland.archaeology.restoration.RestorationBook.*;
/** Stable identity, frozen recipe and consumption invariant tests, without inventory or bank substitutes. */
public final class RestorationBookSmoke {
    static int checks;static final Recipe RECIPE=new Recipe("clay_seal","common",3);static final UUID PLAYER=UUID.randomUUID();static void check(boolean good,String why){checks++;if(!good)throw new AssertionError(why);}static void denied(Runnable action,String why){try{action.run();}catch(IllegalArgumentException expected){check(true,why);return;}throw new AssertionError(why);}
    static Fragment fragment(int part){return new Fragment(UUID.randomUUID(),UUID.randomUUID(),PLAYER,"Finder",RECIPE,part,100,FragmentPhase.MAILBOX,null);}
    static Source source(Fragment fragment){return new Source(fragment.source(),"site:block:"+fragment.source(),PLAYER,"Finder",100,fragment.id());}
    static Operation claim(Fragment fragment){return new Operation(UUID.randomUUID(),Kind.CLAIM,PLAYER,"Finder",200,RECIPE,List.of(fragment.id()),fragment.id(),"AA==",Phase.PREPARED,"Получение");}
    static Operation restore(UUID actor,List<UUID> fragments){return new Operation(UUID.randomUUID(),Kind.RESTORE,actor,"Restorer",300,RECIPE,fragments,UUID.randomUUID(),"AA==",Phase.PREPARED,"Реставрация");}
    public static void main(String[] args){
        var a=fragment(1);var b=fragment(2);var c=fragment(3);var state=State.empty().discover(source(a),a);check(state.discover(source(a),a)==state,"identical site-block discovery idempotent");var initial=state;denied(()->initial.discover(new Source(a.source(),source(a).origin(),PLAYER,"Finder",101,null),null),"same source cannot reroll another result");denied(()->initial.discover(new Source(UUID.randomUUID(),source(a).origin(),PLAYER,"Finder",100,null),null),"same physical source cannot receive a fresh receipt ID");check(state.minted(PLAYER,100)==1&&state.minted(null,86_400_100)==0&&state.minted(PLAYER,50)==1,"rolling limit counts confirmed findings, expires after 24h and fails safely if clock moves backward");
        var claim=claim(a);var reserved=state.prepare(claim);check(reserved.fragments().get(a.id()).phase()==FragmentPhase.CLAIMING&&reserved.blocked(PLAYER),"mailbox reserve does not yet claim successful delivery");denied(()->reserved.complete(claim.id()),"prepared inventory cannot be called delivered");denied(()->reserved.prepare(claim(a)),"one unfinished inventory operation per player");var cancelled=reserved.cancelPrepared(claim.id(),"Инвентарь не менялся");check(cancelled.fragments().get(a.id()).phase()==FragmentPhase.MAILBOX&&!cancelled.blocked(PLAYER),"pre-transfer cancellation safely releases mailbox reservation");
        var armed=reserved.arm(claim.id());denied(()->armed.cancelPrepared(claim.id(),"Сервер перезапущен"),"absence of a save marker cannot automatically undo an armed delivery");var reviewed=armed.review(claim.id(),"Сохранение игрока не подтверждено");check(reviewed.fragments().get(a.id()).phase()==FragmentPhase.CLAIMING&&reviewed.blocked(PLAYER),"unknown delivery stays reserved and cannot auto retry");state=reviewed.complete(claim.id());check(state.fragments().get(a.id()).phase()==FragmentPhase.OWNED&&state.complete(claim.id())==state,"confirmed transfer records exact item identity once");var own=state;denied(()->own.prepare(claim(a)),"already delivered fragment cannot be obtained twice");
        state=state.discover(source(b),b).discover(source(c),c);for(var fragment:List.of(b,c)){var op=claim(fragment);state=state.prepare(op).arm(op.id()).complete(op.id());}var ready=state;var parts=List.of(a.id(),b.id(),c.id());denied(()->new Operation(UUID.randomUUID(),Kind.RESTORE,PLAYER,"Name",300,RECIPE,List.of(a.id(),a.id(),c.id()),UUID.randomUUID(),"AA==",Phase.PREPARED,"Duplicate"),"copied UUID is never a second required fragment");
        var other=fragment(1);state=state.discover(source(other),other);var claimOther=claim(other);state=state.prepare(claimOther).arm(claimOther.id()).complete(claimOther.id());var wrongParts=state;denied(()->wrongParts.prepare(restore(PLAYER,List.of(a.id(),other.id(),c.id()))),"two pieces with same part index do not complete a set");var restoration=restore(UUID.randomUUID(),parts);state=ready.prepare(restoration);check(state.fragments().get(a.id()).phase()==FragmentPhase.RESERVED&&state.operations().get(restoration.id()).recipe().equals(RECIPE),"traded physical pieces use frozen original recipe and exact reservations");var next=state.arm(restoration.id()).complete(restoration.id());check(parts.stream().allMatch(id->next.fragments().get(id).phase()==FragmentPhase.SPENT)&&next.complete(restoration.id())==next,"one confirmed restoration consumes every exact input once");denied(()->next.prepare(restore(PLAYER,parts)),"spent signed copies cannot fund another exhibit");
        var broken=new HashMap<>(next.fragments());broken.put(a.id(),next.fragments().get(a.id()).phase()==FragmentPhase.SPENT?a:null);denied(()->new State(next.sources(),broken,next.operations(),next.revision()),"state loader rejects completed output without consumed input identities");
        denied(()->new Recipe("clay_seal","common",2),"recipe requires bounded multiple distinct parts");denied(()->new Recipe("path.escape","common",3),"new identifiers do not accept YAML path separators");
        System.out.println("RestorationBookSmoke PASS "+checks+" checks");
    }
}
